llel {\n                    Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 2, \"linear\"),\n                    Ease(scene.objectLookup.Cheetah, \"y\", function() return scene.objectLookup.Cheetah.y - 100 end, 4),\n                },\n                Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 2, \"linear\"),\n                Parallel {\n                    Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 4, \"linear\"),\n                    Ease(scene.objectLookup.Cheetah, \"y\", function() return scene.objectLookup.Cheetah.y + 600 end, 6),\n                }\n            }\n        },\n        Do(function() scene.objectLookup.Snively.sprite:setAnimation(\"idleright_laugh\") end),\n        Wait(2),\n        Do(function() scene.objectLookup.Snively.sprite:setAnimation(\"idleright_smile\") end),\n        MessageBox{message=\"Snively: Now the Princess and her little hedgehog will be hopelessly trapped{p80}, deep within the inescapable {h robot wasteland}...\", textSpeed=3, closeAction=Wait(5)},\n        TypeText(\n            Transform(50, 300),\n            {255, 255, 255, 255},\n            FontCache.Techno,\n            \"TO BE CONTINUED...\",\n            3\n        ),\n        Wait(2),\n        Do(function()\n            scene.sceneMgr:pushScene {class = \"CreditsSplashScene\"}\n        end)\n    }\nend"
